import{_ as d,o as r,c as a,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"अंधकार प्रतिस्थापन इकाइयों की चार शाखाओं का निपटान","description":"","frontmatter":{},"headers":[],"relativePath":"hi/59-黑暗置换体四类分支处置.md","filePath":"hi/59-黑暗置换体四类分支处置.md"}'),i={name:"hi/59-黑暗置换体四类分支处置.md"};function e(h,t,o,n,s,b){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="अंधकार-प्रतिस्थापन-इकाइयों-की-चार-शाखाओं-का-निपटान" tabindex="-1">अंधकार प्रतिस्थापन इकाइयों की चार शाखाओं का निपटान <a class="header-anchor" href="#अंधकार-प्रतिस्थापन-इकाइयों-की-चार-शाखाओं-का-निपटान" aria-label="Permalink to &quot;अंधकार प्रतिस्थापन इकाइयों की चार शाखाओं का निपटान&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>59</td></tr><tr><td>मॉड्यूल</td><td>जातियाँ और जीवन-रूप</td></tr><tr><td>कीवर्ड</td><td>संलयन-सहजीवन, पृथक्करण-स्थापन, सील-निगरानी, विघटन, शाखा-निपटान</td></tr></tbody></table><h2 id="i-शाखा-निपटान-की-समग्र-रूपरेखा" tabindex="-1">I. शाखा-निपटान की समग्र रूपरेखा <a class="header-anchor" href="#i-शाखा-निपटान-की-समग्र-रूपरेखा" aria-label="Permalink to &quot;I. शाखा-निपटान की समग्र रूपरेखा&quot;">​</a></h2><p>अंधकार प्रतिस्थापन इकाइयों का निपटान लंगर सहजीवी सभ्यता के जीवन-शासन का सबसे जटिल क्षेत्र है। विचित्र जीवन और विचित्र ऊर्जा की तीन-प्रकार निपटान-प्रक्रियाओं से भिन्न, अंधकार प्रतिस्थापन इकाइयों को उनकी विशेष द्वि-आत्मा सह-अस्तित्व संरचना (देखें <em>57-黑暗置换体起源与本质</em>) के कारण अधिक परिष्कृत शाखा-निपटान योजनाओं की आवश्यकता होती है। <em>58-双魂伦理准则</em> में स्थापित नैतिक सिद्धांतों के अनुसार, अंधकार प्रतिस्थापन इकाई के विकास-चरण, मूल स्वामी आत्मा की स्थिति, अंधकार-आत्मा की विशेषताओं और जोखिम-स्तर के साथ मिलाकर, अंधकार प्रतिस्थापन इकाइयों का निपटान चार शाखाओं में विभाजित है: संलयन-सहजीवन प्रकार, पृथक्करण-स्थापन प्रकार, सील-निगरानी प्रकार, विघटन प्रकार।</p><p>चार शाखाओं के निपटान का चयन निम्न निर्णय-तर्क का पालन करता है:</p><table tabindex="0"><thead><tr><th>निर्णय-कारक</th><th>विचारणीय बिंदु</th></tr></thead><tbody><tr><td>विकास-चरण</td><td>प्रथम से तृतीय चरण तक बचाव को प्राथमिकता; चतुर्थ चरण सतर्क मूल्यांकन; पंचम चरण में मूल स्वामी समाप्त</td></tr><tr><td>मूल स्वामी आत्मा की स्थिति</td><td>क्या मूल स्वामी आत्मा अभी मौजूद है, क्या इच्छा व्यक्त कर सकती है, क्या पुनर्प्राप्ति की संभावना है</td></tr><tr><td>अंधकार-आत्मा की विशेषताएँ</td><td>क्या अंधकार-आत्मा में संवाद-क्षमता है, क्या सुधार की गुंजाइश है, विनाशकारिता की मात्रा</td></tr><tr><td>जोखिम-स्तर</td><td>सार्वजनिक सुरक्षा और दूसरों के अधिकारों-हितों के लिए खतरे की मात्रा</td></tr><tr><td>नैतिक समीक्षा निष्कर्ष</td><td>द्वि-आत्मा नैतिक समीक्षा समिति की समीक्षा-राय और निर्णय</td></tr><tr><td>मूल स्वामी की इच्छा</td><td>मूल स्वामी आत्मा का चुनाव जब वह इच्छा व्यक्त कर सकती है</td></tr></tbody></table><h2 id="ii-प्रथम-प्रकार-संलयन-सहजीवन-निपटान" tabindex="-1">II. प्रथम प्रकार: संलयन-सहजीवन निपटान <a class="header-anchor" href="#ii-प्रथम-प्रकार-संलयन-सहजीवन-निपटान" aria-label="Permalink to &quot;II. प्रथम प्रकार: संलयन-सहजीवन निपटान&quot;">​</a></h2><p>संलयन-सहजीवन निपटान चार शाखाओं में सबसे सकारात्मक और रचनात्मक निपटान-विधि है, उन अंधकार प्रतिस्थापन इकाइयों पर लागू जिनमें मूल स्वामी आत्मा और अंधकार-आत्मा के बीच मेल-मिलाप और आत्मा-संलयन की संभावना हो।</p><h3 id="_1-लागू-शर्तें" tabindex="-1">(1) लागू-शर्तें <a class="header-anchor" href="#_1-लागू-शर्तें" aria-label="Permalink to &quot;(1) लागू-शर्तें&quot;">​</a></h3><p>संलयन-सहजीवन निपटान के लिए निम्न शर्तें एक साथ पूरी होनी चाहिए:</p><ol><li>अंधकार प्रतिस्थापन इकाई तृतीय चरण (द्वि-आत्मा निर्माण काल) या चतुर्थ चरण के आरंभ (अंधकार-प्रमुखता काल का आरंभ) में हो; मूल स्वामी आत्मा अभी मौजूद हो और कुछ स्वायत्त चेतना रखती हो।</li><li>मूल स्वामी आत्मा स्पष्ट रूप से अंधकार-आत्मा के साथ संलयन का प्रयास करने की इच्छा व्यक्त करे, और यह इच्छा वास्तविक और स्वायत्त मानी जाए।</li><li>अंधकार-आत्मा में कुछ संवाद-क्षमता हो, विशुद्ध विनाशकारी न होने वाली विशेषताएँ दिखाए, और संलयन स्वीकार करने की संभावना हो।</li><li>जोखिम-स्तर द्वितीय स्तर (मध्य जोखिम) या उससे नीचे मूल्यांकित हो, और संलयन-प्रक्रिया सार्वजनिक सुरक्षा के लिए अनियंत्रित खतरा न बनाए।</li><li>द्वि-आत्मा नैतिक समीक्षा समिति की समीक्षा-स्वीकृति।</li></ol><h3 id="_2-निपटान-लक्ष्य" tabindex="-1">(2) निपटान-लक्ष्य <a class="header-anchor" href="#_2-निपटान-लक्ष्य" aria-label="Permalink to &quot;(2) निपटान-लक्ष्य&quot;">​</a></h3><p>मूल स्वामी आत्मा और अंधकार-आत्मा को मेल-मिलाप की ओर ले जाकर दोनों आत्माओं का जैविक संलयन प्राप्त करना, ऐसी नई आत्मा बनाना जिसमें मूल स्वामी की स्मृतियाँ, व्यक्तित्व और अंधकार-शक्ति दोनों हों। संलयित नई आत्मा मूल स्वामी की नागरिकता और वैध अधिकार बनाए रखती है, साथ ही अंधकार-ऊर्जा नियंत्रण की क्षमता प्राप्त कर सहजीवी सभ्यता की विशेष सदस्य बनती है।</p><h3 id="_3-निपटान-चरण" tabindex="-1">(3) निपटान-चरण <a class="header-anchor" href="#_3-निपटान-चरण" aria-label="Permalink to &quot;(3) निपटान-चरण&quot;">​</a></h3><table tabindex="0"><thead><tr><th>चरण</th><th>नाम</th><th>विशिष्ट सामग्री</th><th>जिम्मेदार संस्था</th></tr></thead><tbody><tr><td>प्रथम चरण</td><td>नैतिक समीक्षा</td><td>द्वि-आत्मा नैतिक समीक्षा समिति संलयन-योजना की सम्पूर्ण समीक्षा, नैतिक सिद्धांतों के अनुरूप पुष्टि</td><td>द्वि-आत्मा नैतिक समीक्षा समिति</td></tr><tr><td>द्वितीय चरण</td><td>संवाद-मार्गदर्शन</td><td>नियंत्रित वातावरण में पेशेवर आत्मा-मार्गदर्शक मूल स्वामी आत्मा और अंधकार-आत्मा के संवाद में सहायता, परस्पर समझ बढ़ाना</td><td>आत्मा-उपचार केंद्र + साधक</td></tr><tr><td>तृतीय चरण</td><td>मेल-मिलाप वार्ता</td><td>दोनों आत्माओं को संलयन के बाद की पहचान, स्मृतियों, क्षमताओं, व्यवहार-मानकों आदि पर मेल-मिलाप समझौता करने का मार्गदर्शन</td><td>आत्मा-उपचार केंद्र + कानूनी सलाहकार</td></tr><tr><td>चतुर्थ चरण</td><td>संलयन-तैयारी</td><td>संलयन से पहले शरीर-तैयारी, ऊर्जा-संतुलन, मनोवैज्ञानिक-निर्माण आदि तैयारियाँ</td><td>चिकित्सा-दल + साधना-मार्गदर्शक</td></tr><tr><td>पंचम चरण</td><td>आत्मा-संलयन</td><td>उच्च साधकों और आत्मा-चिकित्सकों के संयुक्त सहयोग से आत्मा-संलयन शल्यक्रिया/अनुष्ठान</td><td>उच्च साधक + आत्मा-चिकित्सक</td></tr><tr><td>षष्ठ चरण</td><td>संलयनोत्तर स्थिरीकरण</td><td>संलयित नई आत्मा का स्थिरीकरण-उपचार, आत्मा-पूर्णता और शरीर-अनुकूलता की निगरानी</td><td>चिकित्सा-दल + निगरानी-दल</td></tr><tr><td>सप्तम चरण</td><td>पहचान-पुष्टि</td><td>संलयित नई आत्मा की पहचान पुष्टि, मूल स्वामी की नागरिकता बनाए रखना, पहचान-अभिलेख अद्यतन</td><td>जनगणना-संस्था + जीवन प्रशासन ब्यूरो</td></tr><tr><td>अष्टम चरण</td><td>समावेशन-सहायता</td><td>संलयित व्यक्ति को मनोवैज्ञानिक-परामर्श, साधना-मार्गदर्शन, सामाजिक-समावेशन आदि सहायक सेवाएँ</td><td>दस हजार जाति कार्य विभाग + समुदाय</td></tr><tr><td>नवम चरण</td><td>दीर्घकालिक अनुशीलन</td><td>संलयित व्यक्ति की कम से कम पाँच वर्ष दीर्घकालिक अनुशीलन-निगरानी, संलयन-स्थिरता और सामाजिक-अनुकूलता का आकलन</td><td>जीवन प्रशासन ब्यूरो + समुदाय</td></tr></tbody></table><h3 id="_4-संलयनोत्तर-प्रबंधन" tabindex="-1">(4) संलयनोत्तर प्रबंधन <a class="header-anchor" href="#_4-संलयनोत्तर-प्रबंधन" aria-label="Permalink to &quot;(4) संलयनोत्तर प्रबंधन&quot;">​</a></h3><p>संलयित व्यक्ति मूल स्वामी की नागरिकता बनाए रखने पर भी विशेष प्रबंधन स्वीकार करे:</p><ul><li><strong>ऊर्जा-नियंत्रण</strong>: संलयित व्यक्ति का अंधकार-ऊर्जा उपयोग कठोर नियंत्रित; नियमित ऊर्जा-परीक्षण आवश्यक, सार्वजनिक स्थानों में अंधकार-ऊर्जा उपयोग निषिद्ध।</li><li><strong>व्यवहार-पर्यवेक्षण</strong>: संलयित व्यक्ति नियमित रूप से जीवन प्रशासन ब्यूरो को व्यवहार-स्थिति रिपोर्ट करे, समुदाय की पर्यवेक्षण और सहायता स्वीकार करे।</li><li><strong>साधना-प्रतिबंध</strong>: संलयित व्यक्ति अंधकार-गुण बढ़ाने वाली विधियों का साधन न करे; साधना-योजनाएँ स्वीकृति-आवश्यक।</li><li><strong>आपात-योजना</strong>: संलयित व्यक्ति के अंधकार-अनियंत्रण हेतु आपात-योजना; अनियंत्रण के संकेत पर तुरंत नियंत्रण सक्रिय।</li><li><strong>निकास-तंत्र</strong>: संलयन के बाद गंभीर अस्थिरता या निरंतर खतरनाक व्यवहार पर पुनर्मूल्यांकन कर अन्य निपटान-प्रकार में बदला जा सकता है।</li></ul><h3 id="_5-संलयन-विफलता-का-उपचार" tabindex="-1">(5) संलयन-विफलता का उपचार <a class="header-anchor" href="#_5-संलयन-विफलता-का-उपचार" aria-label="Permalink to &quot;(5) संलयन-विफलता का उपचार&quot;">​</a></h3><p>आत्मा-संलयन में विफलता-जोखिम है; विफलता के उपचार-योजनाएँ:</p><ul><li><strong>संलयन-व्यवधान</strong>: संलयन-प्रक्रिया में गंभीर अस्थिरता पर तुरंत संलयन रोकना, दोनों आत्माओं को संलयन-पूर्व स्थिति में लौटाना।</li><li><strong>अपूर्ण संलयन</strong>: संलयन के बाद आत्मा-अपूर्णता या व्यक्तित्व-विभाजन पर पृथक्करण-स्थापन निपटान में स्थानांतरित।</li><li><strong>संलयन-अनियंत्रण</strong>: संलयन के बाद नई आत्मा में अनियंत्रित विनाशकारिता पर तुरंत सील-निगरानी या विघटन निपटान में स्थानांतरित।</li></ul><h2 id="iii-द्वितीय-प्रकार-पृथक्करण-स्थापन-निपटान" tabindex="-1">III. द्वितीय प्रकार: पृथक्करण-स्थापन निपटान <a class="header-anchor" href="#iii-द्वितीय-प्रकार-पृथक्करण-स्थापन-निपटान" aria-label="Permalink to &quot;III. द्वितीय प्रकार: पृथक्करण-स्थापन निपटान&quot;">​</a></h2><p>पृथक्करण-स्थापन निपटान उन अंधकार प्रतिस्थापन इकाइयों पर लागू होता है जिनमें मूल स्वामी आत्मा और अंधकार-आत्मा संलयन नहीं कर सकतीं किंतु पृथक हो सकती हैं; आत्मा-पृथक्करण शल्यक्रिया से दोनों आत्माएँ अलग कर क्रमशः स्थापित की जाती हैं।</p><h3 id="_1-लागू-शर्तें-1" tabindex="-1">(1) लागू-शर्तें <a class="header-anchor" href="#_1-लागू-शर्तें-1" aria-label="Permalink to &quot;(1) लागू-शर्तें&quot;">​</a></h3><ol><li>अंधकार प्रतिस्थापन इकाई तृतीय या चतुर्थ चरण में हो; मूल स्वामी आत्मा अभी मौजूद हो और पुनर्प्राप्ति की संभावना हो।</li><li>दोनों आत्माओं का संलयन-प्रयास विफल हो या संलयन की शर्तें न हों।</li><li>तकनीकी-आकलन आत्मा-पृथक्करण को व्यवहार्य माने, और पृथक्करण के बाद मूल स्वामी आत्मा स्वतंत्र रूप से जीवित रह सके।</li><li>मूल स्वामी आत्मा स्पष्ट रूप से पृथक्करण की इच्छा व्यक्त करे।</li><li>द्वि-आत्मा नैतिक समीक्षा समिति की समीक्षा-स्वीकृति।</li></ol><h3 id="_2-निपटान-लक्ष्य-1" tabindex="-1">(2) निपटान-लक्ष्य <a class="header-anchor" href="#_2-निपटान-लक्ष्य-1" aria-label="Permalink to &quot;(2) निपटान-लक्ष्य&quot;">​</a></h3><p>आत्मा-पृथक्करण शल्यक्रिया से मूल स्वामी आत्मा और अंधकार-आत्मा को अलग करना; मूल स्वामी आत्मा शरीर में लौटकर सामान्य जीवन पुनः शुरू करे, जबकि अंधकार-आत्मा को नियंत्रण और अनुसंधान हेतु विशेष कंटेनर या सुविधा में स्थापित किया जाए।</p><h3 id="_3-निपटान-चरण-1" tabindex="-1">(3) निपटान-चरण <a class="header-anchor" href="#_3-निपटान-चरण-1" aria-label="Permalink to &quot;(3) निपटान-चरण&quot;">​</a></h3><table tabindex="0"><thead><tr><th>चरण</th><th>नाम</th><th>विशिष्ट सामग्री</th><th>जिम्मेदार संस्था</th></tr></thead><tbody><tr><td>प्रथम चरण</td><td>नैतिक समीक्षा</td><td>द्वि-आत्मा नैतिक समीक्षा समिति पृथक्करण-योजना की समीक्षा, आवश्यकता और व्यवहार्यता की पुष्टि</td><td>द्वि-आत्मा नैतिक समीक्षा समिति</td></tr><tr><td>द्वितीय चरण</td><td>पृथक्करण-तैयारी</td><td>पृथक्करण से पहले शरीर-आकलन, आत्मा-स्थिति परीक्षण, ऊर्जा-संतुलन समायोजन आदि तैयारियाँ</td><td>चिकित्सा-दल + आत्मा-चिकित्सक</td></tr><tr><td>तृतीय चरण</td><td>आत्मा-पृथक्करण</td><td>उच्च साधकों और आत्मा-चिकित्सकों के सहयोग से आत्मा-पृथक्करण शल्यक्रिया, दोनों आत्माओं को शरीर से अलग करना</td><td>उच्च साधक + आत्मा-चिकित्सक</td></tr><tr><td>चतुर्थ चरण</td><td>मूल स्वामी पुनःस्थापन</td><td>मूल स्वामी आत्मा को शरीर में पुनः प्रत्यारोपित करना, आत्मा-स्थिरीकरण और शरीर-पुनर्वास उपचार</td><td>चिकित्सा-दल</td></tr><tr><td>पंचम चरण</td><td>अंधकार-स्थापन</td><td>पृथक की गई अंधकार-आत्मा को विशेष आत्मा-कंटेनमेंट कंटेनर में रखना और आत्मा-सील सुविधा में संग्रहित करना</td><td>जीवन प्रशासन ब्यूरो + तकनीकी-दल</td></tr><tr><td>षष्ठ चरण</td><td>मूल स्वामी पुनर्वास</td><td>मूल स्वामी का सम्पूर्ण शारीरिक-पुनर्वास, मनोवैज्ञानिक-उपचार, साधना-पुनर्प्राप्ति, सामान्य जीवन में वापसी में सहायता</td><td>चिकित्सा-दल + मनोवैज्ञानिक-परामर्शदाता</td></tr><tr><td>सप्तम चरण</td><td>पहचान-पुनर्स्थापन</td><td>मूल स्वामी की पहचान और अधिकारों की पूर्ण पुनर्स्थापना पुष्टि, पहचान-अभिलेख अद्यतन</td><td>जनगणना-संस्था</td></tr><tr><td>अष्टम चरण</td><td>अंधकार-आत्मा प्रबंधन</td><td>पृथक अंधकार-आत्मा की निरंतर निगरानी और अनुसंधान, उसके सुधार या विघटन की संभावना खोजना</td><td>जीवन प्रशासन ब्यूरो + वैज्ञानिक-अनुसंधान संस्था</td></tr></tbody></table><h3 id="_4-पृथक-अंधकार-आत्मा-की-स्थापना" tabindex="-1">(4) पृथक अंधकार-आत्मा की स्थापना <a class="header-anchor" href="#_4-पृथक-अंधकार-आत्मा-की-स्थापना" aria-label="Permalink to &quot;(4) पृथक अंधकार-आत्मा की स्थापना&quot;">​</a></h3><p>पृथक अंधकार-आत्मा निम्न विधि से स्थापित की जाती है:</p><ul><li><strong>आत्मा-कंटेनर</strong>: अंधकार-आत्मा विशेष आत्मा-कंटेनमेंट कंटेनर में, जो ऊर्जा-परिरक्षण, चेतना-दमन, सुरक्षा-लॉकिंग आदि उपकरणों से युक्त हो।</li><li><strong>सील-सुविधा</strong>: कंटेनर विशेष आत्मा-सील सुविधा में संग्रहित, जो उच्चतम स्तर का सुरक्षा-प्रबंधन करती है।</li><li><strong>निरंतर निगरानी</strong>: अंधकार-आत्मा की चेतना-गतिविधि और ऊर्जा-उतार-चढ़ाव की 24 घंटे निरंतर निगरानी।</li><li><strong>अनुसंधान-उपयोग</strong>: कठोर नैतिक समीक्षा के अंतर्गत अंधकार-आत्मा पर वैज्ञानिक अनुसंधान, अथाह ऊर्जा के सार और शुद्धिकरण-विधियों की खोज।</li><li><strong>अंतिम निपटान</strong>: अनुसंधान-परिणामों और जोखिम-आकलन के अनुसार अंधकार-आत्मा का अंतिम निपटान-निर्णय — अविनाशकारी अस्तित्व में सुधार, दीर्घकालिक सील, या शुद्धिकरण-विघटन।</li></ul><h3 id="_5-पृथक्करण-जोखिम-और-सामना" tabindex="-1">(5) पृथक्करण-जोखिम और सामना <a class="header-anchor" href="#_5-पृथक्करण-जोखिम-और-सामना" aria-label="Permalink to &quot;(5) पृथक्करण-जोखिम और सामना&quot;">​</a></h3><p>आत्मा-पृथक्करण शल्यक्रिया में निम्न जोखिम हैं, जिनके लिए सामना-योजनाएँ बनानी चाहिए:</p><table tabindex="0"><thead><tr><th>जोखिम</th><th>सामना-योजना</th></tr></thead><tbody><tr><td>पृथक्करण के दौरान मूल स्वामी आत्मा क्षतिग्रस्त</td><td>पृथक्करण से पहले आत्मा-सुदृढ़ीकरण; पृथक्करण में उच्च साधक पूर्ण रक्षा</td></tr><tr><td>पृथक्करण के बाद मूल स्वामी का शरीर अनुकूल नहीं</td><td>पृथक्करण के बाद सम्पूर्ण शारीरिक-पुनर्वास और आत्मा-स्थिरीकरण उपचार</td></tr><tr><td>पृथक्करण के दौरान अंधकार-आत्मा पलायन</td><td>पृथक्करण उच्चतम स्तर की सुरक्षा-सुविधा में, बहु-कंटेनमेंट उपकरणों से युक्त</td></tr><tr><td>अपूर्ण पृथक्करण, अंधकार-ऊर्जा अवशेष</td><td>पृथक्करण के बाद गहन शुद्धिकरण-उपचार, अवशिष्ट अंधकार-ऊर्जा समाप्त</td></tr><tr><td>पृथक्करण के बाद मूल स्वामी आत्मा में मनोवैज्ञानिक-आघात</td><td>दीर्घकालिक मनोवैज्ञानिक-परामर्श और मानसिक-उपचार</td></tr></tbody></table><h2 id="iv-तृतीय-प्रकार-सील-निगरानी-निपटान" tabindex="-1">IV. तृतीय प्रकार: सील-निगरानी निपटान <a class="header-anchor" href="#iv-तृतीय-प्रकार-सील-निगरानी-निपटान" aria-label="Permalink to &quot;IV. तृतीय प्रकार: सील-निगरानी निपटान&quot;">​</a></h2><p>सील-निगरानी निपटान उन अंधकार प्रतिस्थापन इकाइयों पर लागू होता है जो न संलयन कर सकती हैं न पृथक हो सकती हैं, किंतु जिनकी मूल स्वामी आत्मा अभी मौजूद हो और जिनमें तत्काल विघटन की शर्तें न हों; सील-साधनों से उनकी खतरनाकता नियंत्रित की जाती है, दीर्घकालिक निगरानी और निरंतर आकलन के साथ।</p><h3 id="_1-लागू-शर्तें-2" tabindex="-1">(1) लागू-शर्तें <a class="header-anchor" href="#_1-लागू-शर्तें-2" aria-label="Permalink to &quot;(1) लागू-शर्तें&quot;">​</a></h3><ol><li>अंधकार प्रतिस्थापन इकाई चतुर्थ चरण (अंधकार-प्रमुखता काल) में हो; मूल स्वामी आत्मा गहन रूप से दबी किंतु अभी समाप्त नहीं।</li><li>संलयन और पृथक्करण दोनों तकनीकी रूप से अव्यवहार्य हों या जोखिम अत्यधिक हो।</li><li>अंधकार प्रतिस्थापन इकाई का जोखिम-स्तर तृतीय स्तर (उच्च जोखिम) हो, किंतु अभी तत्काल विघटन की आवश्यकता वाली स्थिति तक न पहुँचा हो।</li><li>मूल स्वामी आत्मा में अभी भी धुंधली पुनर्प्राप्ति-संभावना हो, समय और परिस्थितियों की प्रतीक्षा आवश्यक।</li><li>द्वि-आत्मा नैतिक समीक्षा समिति सील-योजना की समीक्षा-स्वीकृति दे।</li></ol><h3 id="_2-निपटान-लक्ष्य-2" tabindex="-1">(2) निपटान-लक्ष्य <a class="header-anchor" href="#_2-निपटान-लक्ष्य-2" aria-label="Permalink to &quot;(2) निपटान-लक्ष्य&quot;">​</a></h3><p>सील-साधनों से अंधकार-आत्मा की शक्ति और गतिविधि दबाना, अंधकार प्रतिस्थापन इकाई की खतरनाकता नियंत्रित करना, साथ ही मूल स्वामी आत्मा को पूर्ण विनाश से बचाना, दीर्घकालिक निगरानी में पुनर्प्राप्ति या निपटान के अवसर परिपक्व होने की प्रतीक्षा।</p><h3 id="_3-सील-विधियाँ" tabindex="-1">(3) सील-विधियाँ <a class="header-anchor" href="#_3-सील-विधियाँ" aria-label="Permalink to &quot;(3) सील-विधियाँ&quot;">​</a></h3><p>अंधकार प्रतिस्थापन इकाई की शक्ति-स्तर और विशेषताओं के अनुसार निम्न सील-विधियाँ चुनी जाती हैं:</p><table tabindex="0"><thead><tr><th>सील-विधि</th><th>सिद्धांत</th><th>लागू वस्तुएँ</th></tr></thead><tbody><tr><td>ऊर्जा-सील</td><td>सील-मंडल या सील-उपकरणों से अंधकार-ऊर्जा के प्रवाह और उत्सर्जन को दबाना</td><td>निम्न-मध्य शक्ति-स्तर की अंधकार प्रतिस्थापन इकाइयाँ</td></tr><tr><td>स्थान-सील</td><td>अंधकार प्रतिस्थापन इकाई को स्वतंत्र पृथक स्थान में सील करना, बाह्य संपर्क काटना</td><td>उच्च शक्ति-स्तर या संक्रामक अंधकार प्रतिस्थापन इकाइयाँ</td></tr><tr><td>चेतना-सील</td><td>अंधकार-आत्मा की चेतना-गतिविधि दबाना, उसे निद्रित या अर्ध-निद्रित अवस्था में लाना</td><td>सक्रिय चेतना और आत्मा-आक्रमण क्षमता वाली अंधकार प्रतिस्थापन इकाइयाँ</td></tr><tr><td>बहु-सील</td><td>एक साथ कई सील-विधियाँ, बहुस्तरीय सुरक्षा</td><td>अत्यंत उच्च शक्ति-स्तर या कई खतरनाक विशेषताओं वाली इकाइयाँ</td></tr><tr><td>लंगर-सील</td><td>लंगर-ऊर्जा के मूल-गुणों से सील, सबसे शक्तिशाली सील-विधि</td><td>ब्रह्मांडीय-स्तर की खतरनाक अंधकार प्रतिस्थापन इकाइयाँ</td></tr></tbody></table><h3 id="_4-निपटान-चरण" tabindex="-1">(4) निपटान-चरण <a class="header-anchor" href="#_4-निपटान-चरण" aria-label="Permalink to &quot;(4) निपटान-चरण&quot;">​</a></h3><table tabindex="0"><thead><tr><th>चरण</th><th>नाम</th><th>विशिष्ट सामग्री</th><th>जिम्मेदार संस्था</th></tr></thead><tbody><tr><td>प्रथम चरण</td><td>नैतिक समीक्षा</td><td>द्वि-आत्मा नैतिक समीक्षा समिति सील-योजना की समीक्षा, आवश्यकता और उपयुक्तता की पुष्टि</td><td>द्वि-आत्मा नैतिक समीक्षा समिति</td></tr><tr><td>द्वितीय चरण</td><td>सील-तैयारी</td><td>सील-मंडल/उपकरण/स्थान तैयार, सील हेतु आवश्यक ऊर्जा और कर्मी आवंटित</td><td>तकनीकी-दल + उच्च साधक</td></tr><tr><td>तृतीय चरण</td><td>वशीकरण-नियंत्रण</td><td>सुरक्षा-दल के सहयोग से अंधकार प्रतिस्थापन इकाई को वश में करना, सील-प्रक्रिया में दुर्घटना न हो सुनिश्चित</td><td>सुरक्षा सुरक्षा विभाग + उच्च साधक</td></tr><tr><td>चतुर्थ चरण</td><td>सील-क्रियान्वयन</td><td>सील-योजना के अनुसार सील करना, अंधकार-आत्मा की शक्ति और गतिविधि दबाना</td><td>उच्च साधक + सीलकर्ता</td></tr><tr><td>पंचम चरण</td><td>सील-सत्यापन</td><td>सील की प्रभावकारिता और स्थिरता सत्यापित, अंधकार प्रतिस्थापन इकाई की खतरनाकता नियंत्रित होने की पुष्टि</td><td>तकनीकी-दल + निगरानी-दल</td></tr><tr><td>षष्ठ चरण</td><td>स्थानांतरण-स्थापन</td><td>सील की गई अंधकार प्रतिस्थापन इकाई को विशेष सील-निगरानी सुविधा में स्थानांतरित</td><td>सुरक्षा सुरक्षा विभाग + जीवन प्रशासन ब्यूरो</td></tr><tr><td>सप्तम चरण</td><td>निरंतर निगरानी</td><td>सील-स्थिति की 24 घंटे निरंतर निगरानी, नियमित रूप से सील की स्थिरता जाँच</td><td>निगरानी-दल</td></tr><tr><td>अष्टम चरण</td><td>नियमित पुनर्मूल्यांकन</td><td>प्रति छह माह सम्पूर्ण पुनर्मूल्यांकन: मूल स्वामी आत्मा की स्थिति, अंधकार-आत्मा की विशेषताएँ, सील की स्थिरता; निपटान-प्रकार बदलने की संभावना का निर्धारण</td><td>पहचान विशेषज्ञ-समूह + नैतिक समीक्षा समिति</td></tr><tr><td>नवम चरण</td><td>सील-रखरखाव</td><td>नियमित रूप से सील का रखरखाव और सुदृढ़ीकरण, क्षीणता या टूटन रोकना</td><td>सीलकर्ता + तकनीकी-दल</td></tr></tbody></table><h3 id="_5-सील-निगरानी-सुविधा-मानक" tabindex="-1">(5) सील-निगरानी सुविधा मानक <a class="header-anchor" href="#_5-सील-निगरानी-सुविधा-मानक" aria-label="Permalink to &quot;(5) सील-निगरानी सुविधा मानक&quot;">​</a></h3><ul><li><strong>स्थल</strong>: सील-निगरानी सुविधाएँ भूगर्भिक रूप से स्थिर, ऊर्जा-वातावरण स्थिर, कम आबादी वाले दूरस्थ क्षेत्रों में, या स्वतंत्र पृथक पटलों में।</li><li><strong>निर्माण</strong>: सुविधाएँ बहुस्तरीय सुरक्षा-संरचना: भौतिक-अवरोध, ऊर्जा-अवरोध, स्थान-लॉकिंग तीन परतें।</li><li><strong>उपकरण</strong>: उच्च-परिशुद्धता सील-निगरानी उपकरण, स्वचालित सुदृढ़ीकरण-प्रणाली, आपात-प्रतिक्रिया-प्रणाली, आरक्षित ऊर्जा-प्रणाली।</li><li><strong>कर्मी</strong>: 24 घंटे ड्यूटी-प्रणाली, सीलकर्ता, निगरानीकर्ता, सुरक्षा-रक्षक, आपात-उपचार कर्मी।</li><li><strong>आपात</strong>: सील-टूटन, अंधकार-आत्मा पलायन, मूल स्वामी आत्मा विनाश आदि के लिए आपात-योजनाएँ, नियमित अभ्यास।</li></ul><h3 id="_6-सील-का-हटाना-और-परिवर्तन" tabindex="-1">(6) सील का हटाना और परिवर्तन <a class="header-anchor" href="#_6-सील-का-हटाना-और-परिवर्तन" aria-label="Permalink to &quot;(6) सील का हटाना और परिवर्तन&quot;">​</a></h3><p>निम्न परिस्थितियों में सील हटाई जा सकती है या निपटान-प्रकार बदला जा सकता है:</p><ul><li><strong>मूल स्वामी पुनर्प्राप्ति</strong>: सील-काल में मूल स्वामी आत्मा धीरे-धीरे पुनर्प्राप्त हो और पृथक्करण या संलयन की शर्तें हों, सील हटाकर पृथक्करण-स्थापन या संलयन-सहजीवन में बदलना।</li><li><strong>अंधकार-सुधार</strong>: सील-काल में अंधकार-आत्मा सुधार-क्षमता दिखाए, नियंत्रित परिस्थितियों में सील हटाकर सुधार-प्रयास।</li><li><strong>सील-विफलता</strong>: सील में अपूरणीय टूटन या क्षीणता, और अंधकार प्रतिस्थापन इकाई की खतरनाकता अनियंत्रित, विघटन-प्रकार में बदलना।</li><li><strong>मूल स्वामी विनाश</strong>: सील-काल में मूल स्वामी आत्मा पूर्ण समाप्त, अंधकार प्रतिस्थापन इकाई शुद्ध अंधकार-अस्तित्व, खतरनाकता के अनुसार विघटन में बदलना या सील जारी रखना।</li></ul><h2 id="v-चतुर्थ-प्रकार-विघटन-निपटान" tabindex="-1">V. चतुर्थ प्रकार: विघटन निपटान <a class="header-anchor" href="#v-चतुर्थ-प्रकार-विघटन-निपटान" aria-label="Permalink to &quot;V. चतुर्थ प्रकार: विघटन निपटान&quot;">​</a></h2><p>विघटन निपटान चार शाखाओं में सबसे कठोर निपटान-विधि है, उन अंधकार प्रतिस्थापन इकाइयों पर लागू जो बचाई नहीं जा सकतीं और अत्यंत खतरनाक हैं; अंधकार-आत्मा का विनाश (और आवश्यकता पड़ने पर पूरे शरीर का विनाश) कर खतरा समाप्त किया जाता है।</p><h3 id="_1-लागू-शर्तें-3" tabindex="-1">(1) लागू-शर्तें <a class="header-anchor" href="#_1-लागू-शर्तें-3" aria-label="Permalink to &quot;(1) लागू-शर्तें&quot;">​</a></h3><p>विघटन निपटान निम्न परिस्थितियों में लागू:</p><ol><li>अंधकार प्रतिस्थापन इकाई पंचम चरण (पूर्ण प्रतिस्थापन काल) में हो; मूल स्वामी आत्मा पूर्ण समाप्त, शरीर अंधकार-आत्मा के पूर्ण नियंत्रण में, शुद्ध अंधकार-अस्तित्व बन चुका हो।</li><li>अंधकार प्रतिस्थापन इकाई चतुर्थ चरण में हो; मूल स्वामी आत्मा अभी मौजूद किंतु पुनर्प्राप्ति असंभव, संलयन-पृथक्करण-सील सभी अव्यवहार्य, और खतरनाकता निरंतर बढ़ रही हो।</li><li>अंधकार प्रतिस्थापन इकाई का जोखिम-स्तर चतुर्थ स्तर (अत्यंत उच्च जोखिम) हो, ब्रह्मांडीय-स्तर विनाश-शक्ति के साथ, सभ्यता के अस्तित्व को सीधा खतरा, और अन्य निपटान-विधियाँ खतरा नियंत्रित न कर सकें।</li><li>सील-निगरानी निपटान में सील विफल हो और पुनः सील न हो सके, अंधकार प्रतिस्थापन इकाई की खतरनाकता अनियंत्रित हो।</li><li>द्वि-आत्मा नैतिक समीक्षा समिति विघटन-योजना की समीक्षा-स्वीकृति (अत्यंत उच्च जोखिम आपात में पहले निपटान फिर पूर्वव्यापी स्वीकृति)।</li></ol><h3 id="_2-विघटन-सिद्धांत" tabindex="-1">(2) विघटन-सिद्धांत <a class="header-anchor" href="#_2-विघटन-सिद्धांत" aria-label="Permalink to &quot;(2) विघटन-सिद्धांत&quot;">​</a></h3><p>विघटन निपटान जीवन के विनाश से जुड़ा है, और निम्न सिद्धांतों का कठोर पालन करना चाहिए:</p><ul><li><strong>अंतिम-साधन सिद्धांत</strong>: विघटन अन्य सभी निपटान-विधियाँ अव्यवहार्य होने पर अंतिम साधन होना चाहिए।</li><li><strong>अनुपातिकता सिद्धांत</strong>: विघटन की तीव्रता खतरे की मात्रा के अनुरूप हो; अति-बल प्रयोग निषिद्ध।</li><li><strong>न्यूनतम-पीड़ा सिद्धांत</strong>: विघटन यथासंभव पीड़ा-रहित, तीव्र विधि अपनाए, अंधकार-आत्मा (और मौजूद होने पर मूल स्वामी आत्मा) की पीड़ा घटाए।</li><li><strong>मूल स्वामी सम्मान सिद्धांत</strong>: मूल स्वामी आत्मा मौजूद होने पर विघटन से पहले यथासंभव उसे सचेत और गरिमापूर्ण रखना; आवश्यकता पड़ने पर मूल स्वामी को मित्रों-संबंधियों से विदाई देना।</li><li><strong>पूर्ण-अभिलेखन सिद्धांत</strong>: विघटन-प्रक्रिया पूर्ण रूप से अभिलेखित, समीक्षा और अनुशीलन हेतु पूर्ण अभिलेख।</li><li><strong>पश्चात-समीक्षा सिद्धांत</strong>: विघटन पूर्ण होने के बाद पश्चात-समीक्षा, आवश्यकता और उपयुक्तता का आकलन, अनुभव-सबक सारांशित।</li></ul><h3 id="_3-विघटन-विधियाँ" tabindex="-1">(3) विघटन-विधियाँ <a class="header-anchor" href="#_3-विघटन-विधियाँ" aria-label="Permalink to &quot;(3) विघटन-विधियाँ&quot;">​</a></h3><p>अंधकार प्रतिस्थापन इकाई की शक्ति-स्तर और विशेषताओं के अनुसार निम्न विघटन-विधियाँ चुनी जाती हैं:</p><table tabindex="0"><thead><tr><th>विघटन-विधि</th><th>सिद्धांत</th><th>लागू वस्तुएँ</th></tr></thead><tbody><tr><td>पवित्र प्रकाश शुद्धिकरण विघटन</td><td>उच्च-तीव्रता पवित्र प्रकाश ऊर्जा से अंधकार-आत्मा का शुद्धिकरण, उसे प्रकाश में विलीन कराना</td><td>निम्न-मध्य शक्ति-स्तर की अंधकार प्रतिस्थापन इकाइयाँ</td></tr><tr><td>आत्मा-विनाश विद्या</td><td>अंधकार-आत्मा के आत्मा-केंद्र पर सीधा आक्रमण और विनाश, पूर्ण समाप्ति</td><td>उच्च शक्ति-स्तर की अंधकार प्रतिस्थापन इकाइयाँ</td></tr><tr><td>स्थान-निर्वासन विघटन</td><td>अंधकार प्रतिस्थापन इकाई को शून्य-स्थान या काल-अंत में निर्वासित, काल-स्थान क्षय में विघटित</td><td>प्रबल भौतिक-रक्षा वाली अंधकार प्रतिस्थापन इकाइयाँ</td></tr><tr><td>लंगर-मूल विघटन</td><td>लंगर की मूल-ऊर्जा आह्वान, अंधकार प्रतिस्थापन इकाई का विघटन और ब्रह्मांड-मूल में वापसी</td><td>ब्रह्मांडीय-स्तर की खतरनाक अंधकार प्रतिस्थापन इकाइयाँ</td></tr><tr><td>बहु-पटल शक्ति संयुक्त विघटन</td><td>कई पटल-परम शक्तियाँ संयुक्त प्रयास, निरपेक्ष बल से अंधकार प्रतिस्थापन इकाई का दमन और विनाश</td><td>अत्यंत उच्च शक्ति-स्तर की अंधकार प्रतिस्थापन इकाइयाँ</td></tr><tr><td>प्रेरित आत्म-विस्फोट विघटन</td><td>कठोर नियंत्रण में अंधकार प्रतिस्थापन इकाई की अंधकार-ऊर्जा का आत्म-विस्फोट प्रेरित, ऊर्जा-विस्फोट में विघटन</td><td>अस्थिर ऊर्जा वाली अंधकार प्रतिस्थापन इकाइयाँ</td></tr></tbody></table><h3 id="_4-निपटान-चरण-1" tabindex="-1">(4) निपटान-चरण <a class="header-anchor" href="#_4-निपटान-चरण-1" aria-label="Permalink to &quot;(4) निपटान-चरण&quot;">​</a></h3><table tabindex="0"><thead><tr><th>चरण</th><th>नाम</th><th>विशिष्ट सामग्री</th><th>जिम्मेदार संस्था</th></tr></thead><tbody><tr><td>प्रथम चरण</td><td>नैतिक समीक्षा/आपात-अनुमोदन</td><td>सामान्य स्थिति में द्वि-आत्मा नैतिक समीक्षा समिति की समीक्षा-स्वीकृति; अत्यंत उच्च जोखिम आपात में स्थल पर उच्चतम प्रभारी का आदेश, पश्चात अनुमोदन</td><td>द्वि-आत्मा नैतिक समीक्षा समिति / स्थल पर उच्चतम प्रभारी</td></tr><tr><td>द्वितीय चरण</td><td>योजना-निर्माण</td><td>विस्तृत विघटन-योजना: विघटन-विधि, शक्ति-आवंटन, सुरक्षा-उपाय, आपात-योजना, पर्यावरण-प्रभाव आकलन</td><td>युद्ध-कमान मुख्यालय + तकनीकी विशेषज्ञ-समूह</td></tr><tr><td>तृतीय चरण</td><td>शक्ति-एकत्रीकरण</td><td>विघटन हेतु आवश्यक साधक, तकनीकी कर्मी, उपकरण और ऊर्जा-संसाधन एकत्रित</td><td>सुरक्षा सुरक्षा विभाग + उच्च साधक</td></tr><tr><td>चतुर्थ चरण</td><td>क्षेत्र-नाकेबंदी</td><td>विघटन-क्षेत्र की नाकेबंदी, आसपास के कर्मियों की निकासी, सुरक्षा-चेतावनी रेखाएँ</td><td>सुरक्षा सुरक्षा विभाग + स्थानीय सरकार</td></tr><tr><td>पंचम चरण</td><td>वशीकरण-दमन</td><td>पहले दमन-शक्ति से अंधकार प्रतिस्थापन इकाई की गतिविधियाँ नियंत्रित, पलायन या अधिक विनाश रोकना</td><td>उच्च साधक + सुरक्षा-बल</td></tr><tr><td>षष्ठ चरण</td><td>विघटन-क्रियान्वयन</td><td>विघटन-योजना के अनुसार विघटन, प्रक्रिया की पूर्ण निगरानी; किसी असामान्यता पर तुरंत आपात-योजना सक्रिय</td><td>उच्च साधक + तकनीकी-दल</td></tr><tr><td>सप्तम चरण</td><td>विनाश-पुष्टि</td><td>अंधकार-आत्मा (और शरीर) के पूर्ण विनाश की पुष्टि, ऊर्जा-अवशेष या आत्मा-खंडों की जाँच</td><td>निगरानी-दल + पहचान विशेषज्ञ-समूह</td></tr><tr><td>अष्टम चरण</td><td>पर्यावरण-पुनर्स्थापन</td><td>विघटन-क्षेत्र का पर्यावरण-पुनर्स्थापन, अवशिष्ट अंधकार-ऊर्जा समाप्त, पारिस्थितिकी-संतुलन बहाल</td><td>पारिस्थितिकी पर्यावरण विभाग</td></tr><tr><td>नवम चरण</td><td>पश्च-उपचार</td><td>मूल स्वामी के मित्रों-संबंधियों को सूचना (यदि मूल स्वामी समाप्त), मूल स्वामी की संपत्ति का उपचार, मनोवैज्ञानिक-परामर्श</td><td>नागरिक-मामले विभाग + मनोवैज्ञानिक-परामर्शदाता</td></tr><tr><td>दशम चरण</td><td>अभिलेख-संग्रहण और पश्चात-समीक्षा</td><td>विघटन-प्रक्रिया के पूर्ण रिकॉर्ड संग्रहित, पश्चात-समीक्षा, आवश्यकता और उपयुक्तता का आकलन</td><td>जीवन प्रशासन ब्यूरो + नैतिक समीक्षा समिति</td></tr></tbody></table><h3 id="_5-आपातकालीन-विघटन-प्रक्रिया" tabindex="-1">(5) आपातकालीन विघटन-प्रक्रिया <a class="header-anchor" href="#_5-आपातकालीन-विघटन-प्रक्रिया" aria-label="Permalink to &quot;(5) आपातकालीन विघटन-प्रक्रिया&quot;">​</a></h3><p>चतुर्थ स्तर (अत्यंत उच्च जोखिम), सभ्यता के अस्तित्व को सीधे खतरा देने वाली अंधकार प्रतिस्थापन इकाइयों पर आपातकालीन विघटन-प्रक्रिया लागू:</p><ol><li>स्थल पर उच्चतम स्तर का प्रभारी बिना पूर्व नैतिक समीक्षा सीधे आपातकालीन विघटन का आदेश दे सकता है, किंतु विघटन के 24 घंटे के भीतर द्वि-आत्मा नैतिक समीक्षा समिति को पंजीकरण हेतु रिपोर्ट करना होगा।</li><li>आपातकालीन विघटन सभ्यता के उच्चतम स्तर के बल और ऊर्जा-संसाधन जुटा सकता है, जिसमें लंगर-ऊर्जा का केंद्रीकृत आह्वान और कई पटल-परम शक्तियों का संयुक्त प्रयास शामिल।</li><li>आपातकालीन विघटन का प्राथमिक लक्ष्य खतरा समाप्त करना और जीवन तथा सभ्यता की सुरक्षा है, विघटन-विधि की «सुरुचि» या «पीड़ा-रहितता» का पीछा नहीं (किंतु सहवर्ती हानि यथासंभव कम करनी चाहिए)।</li><li>आपातकालीन विघटन के बाद सम्पूर्ण पर्यावरण-आकलन और पुनर्स्थापन, अवशिष्ट अंधकार-ऊर्जा और द्वितीयक आपदाओं की रोकथाम।</li><li>आपातकालीन विघटन के मामलों का अनिवार्य पश्चात-पुनरावलोकन और गहन विश्लेषण, अनुभव-सबक सारांशित, चेतावनी और निपटान-तंत्र सुधार।</li></ol><h2 id="vi-चार-शाखा-निपटानों-का-परिवर्तन-तंत्र" tabindex="-1">VI. चार शाखा निपटानों का परिवर्तन-तंत्र <a class="header-anchor" href="#vi-चार-शाखा-निपटानों-का-परिवर्तन-तंत्र" aria-label="Permalink to &quot;VI. चार शाखा निपटानों का परिवर्तन-तंत्र&quot;">​</a></h2><p>अंधकार प्रतिस्थापन इकाइयों का निपटान अपरिवर्तनीय नहीं है; निपटान-प्रक्रिया में स्थिति-परिवर्तन के अनुसार चार शाखाओं के बीच परिवर्तन संभव है:</p><table tabindex="0"><thead><tr><th>परिवर्तन-दिशा</th><th>परिवर्तन-शर्तें</th><th>परिवर्तन-प्रक्रिया</th></tr></thead><tbody><tr><td>संलयन → पृथक्करण</td><td>संलयन-प्रयास विफल या संलयन के बाद गंभीर अस्थिरता</td><td>पुनर्मूल्यांकन; नैतिक समीक्षा स्वीकृति के बाद पृथक्करण में</td></tr><tr><td>संलयन → सील</td><td>संलयन विफल और पृथक्करण अव्यवहार्य, जोखिम-नियंत्रण आवश्यक</td><td>पुनर्मूल्यांकन; नैतिक समीक्षा स्वीकृति के बाद सील में</td></tr><tr><td>संलयन → विघटन</td><td>संलयन अनियंत्रित, नई आत्मा में अनियंत्रित विनाशकारिता</td><td>आपात-मूल्यांकन; तुरंत विघटन में</td></tr><tr><td>पृथक्करण → सील</td><td>पृथक्करण विफल या पृथक्करण के बाद मूल स्वामी पुनर्प्राप्त नहीं, जोखिम-नियंत्रण आवश्यक</td><td>पुनर्मूल्यांकन; नैतिक समीक्षा स्वीकृति के बाद सील में</td></tr><tr><td>पृथक्करण → विघटन</td><td>पृथक्करण में अंधकार-आत्मा पलायन और अनियंत्रित</td><td>आपात-मूल्यांकन; तुरंत विघटन में</td></tr><tr><td>सील → संलयन</td><td>सील-काल में मूल स्वामी आत्मा पुनर्प्राप्त, संलयन-शर्तें</td><td>नियमित पुनर्मूल्यांकन में पता; नैतिक समीक्षा स्वीकृति के बाद संलयन में</td></tr><tr><td>सील → पृथक्करण</td><td>सील-काल में मूल स्वामी आत्मा पुनर्प्राप्त, पृथक्करण-शर्तें</td><td>नियमित पुनर्मूल्यांकन में पता; नैतिक समीक्षा स्वीकृति के बाद पृथक्करण में</td></tr><tr><td>सील → विघटन</td><td>सील विफल और पुनः सील असंभव, खतरनाकता अनियंत्रित</td><td>आपात-मूल्यांकन; तुरंत विघटन में</td></tr><tr><td>विघटन → अन्य</td><td>विघटन अंतिम साधन; लागू होने पर अनुत्क्रमणीय</td><td>लागू नहीं</td></tr></tbody></table><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>अंधकार प्रतिस्थापन इकाइयों की चार शाखाओं का निपटान लंगर सहजीवी सभ्यता के जीवन-शासन का सर्वोच्च उपलब्धि-रूप है। संलयन-सहजीवन के सक्रिय बचाव से, पृथक्करण-स्थापन के सटीक विभाजन से, सील-निगरानी के धैर्यपूर्ण प्रतीक्षा से, विघटन के अंतिम-साधन तक, चार शाखाएँ सबसे सौम्य से सबसे कठोर तक का पूर्ण निपटान-स्पेक्ट्रम बनाती हैं, अंधकार प्रतिस्थापन इकाइयों की सभी संभावित स्थितियों को आच्छादित करती हैं। यह निपटान-प्रणाली «हर आत्मा को बचाने का पूर्ण प्रयास» की नैतिक निचली रेखा का पालन करते हुए «अनियंत्रित खतरों का दृढ़ उन्मूलन» की सुरक्षा-निचली रेखा भी बनाए रखती है, जो जीवन-नैतिकता और सुरक्षा-शासन के बीच सहजीवी सभ्यता के सूक्ष्म संतुलन को मूर्त रूप देती है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>57-黑暗置换体起源与本质 (अंधकार प्रतिस्थापन इकाइयों की उत्पत्ति और सार)</li><li>58-双魂伦理准则 (द्वि-आत्मा नैतिकता सिद्धांत)</li><li>54-奇特生命三类处置流程 (विचित्र जीवन के तीन प्रकारों की निपटान-प्रक्रिया)</li><li>48-司法体系与裁决机制 (न्यायिक-प्रणाली और निर्णय-तंत्र)</li></ul>',74)])])}const c=d(i,[["render",e]]);export{_ as __pageData,c as default};
